const ICONS = { Shop:"4:163", Explore:"4:130", Cart:"4:121", Favourite:"4:136", Account:"4:118" };
const tabs = ["Shop","Explore","Cart","Favourite","Account"];

async function buildNav(active, x){
  const c = figma.createComponent();
  c.name = "NavBar/Tab="+active; c.x = x; c.y = 800; c.resize(414,84);
  ws.appendChild(c);
  const bg = figma.createRectangle(); bg.name="bg"; bg.x=0; bg.y=0; bg.resize(414,84);
  bg.fills=[{type:"SOLID",color:WHITE}]; bg.topLeftRadius=15; bg.topRightRadius=15;
  bg.effects=[{type:"DROP_SHADOW",color:{r:0,g:0,b:0,a:0.06},offset:{x:0,y:-6},radius:16,spread:0,visible:true,blendMode:"NORMAL"}];
  c.appendChild(bg);
  for (let i=0;i<tabs.length;i++){
    const t = tabs[i];
    const iconComp = await figma.getNodeByIdAsync(ICONS[t]);
    const ic = iconComp.createInstance();
    const size = 24;
    ic.resize(size, size * (iconComp.height/iconComp.width));
    const tabX = i * 82.8 + (82.8-size)/2;
    ic.x = Math.round(tabX); ic.y = 14;
    c.appendChild(ic);
    const isActive = t===active;
    if (isActive){
      const vecs = ic.findAll(n=>n.type==="VECTOR"||n.type==="BOOLEAN_OPERATION"||n.type==="ELLIPSE"||n.type==="RECTANGLE"||n.type==="POLYGON"||n.type==="STAR"||n.type==="LINE");
      for (const vv of vecs){ try{ vv.fills=[{type:"SOLID",color:GREEN}]; }catch(e){} }
    }
    const label = figma.createText(); label.fontName={family:"Poppins",style:"Semi Bold"};
    label.characters=t; label.fontSize=12; label.name="label-"+t;
    label.fills=[{type:"SOLID",color:isActive?GREEN:INK}];
    c.appendChild(label);
    label.x = Math.round(i*82.8 + (82.8-label.width)/2); label.y = 46;
  }
  return c;
}

