const PRODUCTS={ "Organic Bananas":"4:49","Red Apple":"4:55","Bell Pepper Red":"4:28","Ginger":"4:43","Beef Bone":"4:25","Broiler Chicken":"4:31","Egg Chicken Red":"4:40" };

async function makeCard(parent, x, y, name, unit, price){
  const c = await inst(parent,"10:17",x,y);
  setChildrenText(c,{name,unit,price});
  // replace product image: find instance of product image (first INSTANCE child)
  const imgInst = c.findOne(n=>n.type==="INSTANCE");
  const newComp = await figma.getNodeByIdAsync(PRODUCTS[name]);
  imgInst.swapComponent(newComp);
  return c;
}

