  // recreate: take Tab=Favourite variant, recolor
  const fav = navSet.children.find(c=>c.name.includes("Favourite"));
  const acc = fav.clone(); navSet.appendChild(acc);
  acc.name = "Tab=Account";
  // recolor: find icon instance for Account (5th tab) and label-Account
  const labels = acc.findAll(n=>n.type==="TEXT"&&n.name.startsWith("label-"));
  for (const l of labels){
    const tab = l.name.replace("label-","");
    l.characters = l.characters; // keep
    l.fills=[{type:"SOLID",color: tab==="Account"?GREEN:INK}];
  }
  // icons: colour Account icon green, Favourite icon back to ink
  const iconInsts = acc.findAll(n=>n.type==="INSTANCE");
  for (const ic of iconInsts){
    const isAcc = ic.name==="Icon_Account"; const isFav = ic.name==="Icon_Favourite";
    if (isAcc || isFav){
      const vecs = ic.findAll(n=>"fills" in n && n.type!=="TEXT");
      for (const vv of vecs){ try{ vv.fills=[{type:"SOLID",color:isAcc?GREEN:{r:0,g:0,b:0}}]; }catch(e){} }
