  }
  // rewire tab reactions on this new variant
  const F={}; for (const nm of ["05_Home","07_Explore","09_My_Cart","12_Account"]) F[nm]=ws.findOne(x=>x.name===nm);
  const tabDest={Shop:"05_Home",Explore:"07_Explore",Cart:"09_My_Cart",Account:"12_Account"};
